// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;

    function setUp() public { c = new DnGmxBatchingManager(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));

        address initialOwner = c.owner();

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        bool relation = (ok == (caller == initialOwner && c.owner() == newOwner));
        assertTrue(relation);
    }
}
